from h34 import *
M=mcq;F=tf;S=short;N=num
def mala(name):
    def row(y,cols):
        s=''
        for i,c in enumerate(cols): s+=f'<circle cx="{60+i*46}" cy="{y}" r="17" fill="{c}" stroke="#333" stroke-width="2"/>'
        return s
    R='#e63946';B='#1d6fb8'
    b='<text x="380" y="24" text-anchor="middle" font-size="18" font-weight="bold">Symmetrical and not symmetrical malas</text>'
    b+=row(70,[R,R,B,B,B,B,R,R])+'<line x1="237" y1="40" x2="237" y2="100" stroke="#2a9d8f" stroke-width="3" stroke-dasharray="6 4"/><text x="420" y="75" font-size="15">same on both sides: symmetrical</text>'
    b+=row(140,[R,B,B,R,R,B,R,R])+'<text x="420" y="145" font-size="15">two halves differ: not symmetrical</text>'
    svgfile(name,760,180,b)
mala('c3-mala-symmetry.svg')
chapter(3,'maths','the-surajkund-fair','The Surajkund Fair',
 ('Soni and Avi at the fair','Soni and Avi visit the Surajkund Fair, where craft stalls come from all over India. They make malas of beads, see beautiful rangolis and masks, and play a mirror game. Along the way they learn about shapes that look the same on both sides.'),
 [('Symmetry in malas',['A man and a woman at a stall are making malas with beads. Soni and Avi make malas with 8 beads, 4 of one colour and 4 of another.','Some of their malas look the same on both halves, and some do not. If the two halves match exactly, the mala is symmetrical.','A mala with red, red, blue, blue, blue, blue, red, red is symmetrical, because the left half is the mirror of the right half.','A mala with red, blue, blue, red, red, blue, red, red is not symmetrical, because the two halves are different.','We can use 6 beads of one colour and 2 beads of another to make symmetrical malas, by putting 1 bead of the second colour on each side.']),
  ('Symmetry in rangolis',['At the Tamil Nadu stall Amma makes a kolam in front of her hut. Many kolams, rangolis, pookalams and aipans have patterns that match on both sides.','If we draw a line through the middle of a rangoli and the two sides are exactly the same, the rangoli is symmetrical.','We can test it by tracing the rangoli on a paper and folding the paper along the line. If one half lies exactly on the other half, the pattern is symmetrical.','Not all rangolis are symmetrical. Some have a different pattern on each side, and some have more than one line that splits them in two matching halves.','We can complete a half-rangoli by drawing the other half on a dot grid, taking each dot and line to the same distance on the other side of the fold.']),
  ('Masks and the mirror game',['Soni makes a cat mask by folding a paper in half, drawing half a cat, cutting along the line and opening it. The two sides are the same, so the mask is symmetrical.','Avi\'s mask had its eye holes on only one side, so it was not symmetrical, and he could see with one eye.','A painter drew half of a picture and said the other half is just the same. A mirror shows the other half. A trick like this works for symmetrical things, so he should draw things that are not symmetrical.','In the mirror game, one child places counters on one side of a line and the other places counters as a mirror image on the other side. We can check by putting a mirror on the line.']),
  ('Finding symmetry around us',['Many things around us are symmetrical, such as a butterfly, a leaf, a kite and the letters A, H and M.','Some things are not symmetrical, such as a hand, a shoe pair seen as one shoe, or the letter F.','To check, imagine a line through the middle and see whether both sides would match exactly if folded.'])],
 [('A mala has beads in the order red, red, blue, blue, blue, blue, red, red. Is it symmetrical?',[('Split the mala in the middle.','The line of symmetry is in the middle.'),('The left half is red, red, blue, blue and the right half is blue, blue, red, red read the other way.','Compare from the middle outwards.'),('Yes, each bead matches its mirror partner.','So it is symmetrical.')]),
  ('How do we test if a rangoli is symmetrical using tracing paper?',[('Trace the rangoli.','Make a copy of the pattern.'),('Fold the paper so one half falls on the other.','Match the sides.'),('If every line matches exactly, it is symmetrical.','A mismatch means no.')]),
  ('Why could Avi see only with one eye in his mask?',[('His mask had holes only on one side.','The holes were not the same on both sides.'),('So his mask was not symmetrical.','Symmetry needs matching halves.'),('He should have cut both eye holes in the same positions on each half.','Folding first keeps the sides equal.')])],
 ('Explain what it means for a shape to be symmetrical.',['Both halves match exactly','A fold line or mirror line','One half lies on the other','Examples like a butterfly or a mask'],['Any two pieces are symmetrical','A symmetrical shape must be round']),
 ['A shape is symmetrical if the two halves match exactly.','We can test with a fold or a mirror.','Rangolis, malas, masks and butterflies can be symmetrical.','A mirror image is the same picture on the other side of a line.','Not every shape is symmetrical.'],
 [M('1',1,'What does symmetrical mean?','Both halves match exactly',[('Only one half is coloured','Halves must match'),('Large and round','Size does not matter')],'A symmetrical shape matches on both sides.'),
  F('2',1,'All rangolis are symmetrical.',False,'Some rangolis are not symmetrical.'),
  M('3',1,'How can we check the symmetry of a paper cut-out?','Fold it so the halves cover each other',[('Weigh it','Weight does not tell'),('Count its corners','Corners do not tell')],'If the halves cover each other exactly, it is symmetrical.'),
  M('4',1,'Which is symmetrical?','A butterfly',[('A hand','A hand has no matching half'),('The letter F','F is not symmetrical')],'A butterfly has two matching wings.'),
  M('5',2,'A mala is red, blue, blue, red. Is it symmetrical?','Yes',[('No','Both halves match when read from the middle'),('Only if it is round','Shape does not matter')],'Red blue | blue red matches.'),
  M('6',2,'A mala is red, blue, red, red. Is it symmetrical?','No',[('Yes','The halves do not match'),('Maybe','We can decide by comparing')],'The first half red, blue and the second half red, red do not match.'),
  S('7',2,'What do we use in the mirror game to check the mirror image?',['mirror','a mirror'],'We put a mirror on the line.'),
  F('8',2,'Soni\'s mask was symmetrical.',True,'Both halves matched.'),
  F('9',2,'Avi\'s mask was symmetrical.',False,'His eye holes were on one side only.'),
  M('10',2,'Which letter is symmetrical?','A',[('F','F has no matching half'),('R','R has no matching half')],'The letter A matches on both sides of a vertical line.'),
  M('11',3,'Why did the painter\'s trick work?','The other half was a mirror image',[('The picture was very small','Size does not matter'),('He used more colour','Colour does not matter')],'Symmetrical halves match so a mirror shows the rest.'),
  M('12',3,'How many beads of the second colour make a symmetrical mala of 8 beads with 6 of one colour?','2, one on each side',[('2 on the same side','That makes it not symmetrical'),('1 only','Then 7 beads would be left')],'We place one on each side at matching places.')],
 svgs=[('c3-mala-symmetry','Two bead malas, one symmetrical and one not','A symmetrical mala matches on both sides of the middle.')],
 keep=['symmetrical','mirror image','rangoli'])
numberline('c3-hundreds2.svg',600,700,10,[(667,667,'')][:0] or [(650,667,'+17'),(667,700,'+33')],'Reaching 700 from 650')
chapter(3,'maths','house-of-hundreds-2','House of Hundreds - II',
 ('Akbar, Birbal and the crows','Akbar and Birbal are walking in a garden when many crows fly around them. Akbar wants to know how many crows there are in the city. After a day Birbal says there are exactly nine hundred and sixty-three, and he has a clever answer for every doubt Akbar raises. This chapter takes us from 500 up to 1000 and shows how we use hundreds, tens and ones for big numbers.'),
 [('Reading and writing numbers up to 1000',['Numbers can be shown with tiles or blocks of hundreds, tens and ones. Eight hundred thirty-two is 8 hundreds, 3 tens and 2 ones.','A number like 504 has 5 hundreds, no tens and 4 ones. The zero tells us there are no tens.','We can show 620 as 6 hundreds and 2 tens, and 700 as 7 hundreds.','After 900 comes 1000, which is ten hundreds. A 1000-bead string shows how large a thousand is.','We can say a number in words. 947 is nine hundred forty-seven.']),
  ('Neighbours on the number line',['Every number lies between two neighbouring hundreds, two neighbouring fifties and two neighbouring tens.','468 lies between 400 and 500, between 450 and 500, and between 460 and 470.','Number lines help us locate 530, 540, 628, 696 and 590, and later 703, 721, 759, 810, 855 and 887, by counting the steps from the nearest hundred.','On the number line from 650, a crane that starts at 667 reaches 650 by taking 17 steps back, and reaches 700 by taking 33 steps forward.']),
  ('Writing numbers in many ways',['The same number can be made in many ways. 368 is 3 hundreds, 6 tens and 8 ones, and it is also 300 + 60 + 8.','368 is also 68 more than 300, and it is 32 less than 400, because 400 - 32 = 368.','Estimating and comparing help us choose which numbers fit a clue, such as a number between 595 and 605, or two more than 610.','Skip counting helps us complete patterns. We can add 10, 25 or 100 repeatedly and watch which digits change.']),
  ('Making numbers',['With the digits 3 and 8 we can make 2-digit numbers such as 33, 38, 83 and 88 and 3-digit numbers such as 338, 383, 388, 833, 838 and 883, if digits can repeat.','To arrange numbers from smaller to greater we look at the hundreds digit first, then the tens, then the ones.','With paper slips marked 100, 10 or 1 we can make a number. Six slips marked 100 make six hundred, and four slips marked 100 with two marked 10 make 420.','Some numbers cannot be made if the slips do not have the right values, so we must choose the slips carefully.']),
  ('Number words from long ago',['In Bhutasankhya, which means word numerals, a word stands for a number. The Moon stands for 1 because there is one Moon, Eyes stand for 2, Hexagon for 6 and a Palm for 5 fingers.','The seven notes Sa Re Ga Ma Pa Dha Ni stand for 7 because there are seven svaras, and Past, Present and Future stand for 3.','Directions stand for 4. We can make new cards for numbers like 15, 27 and 94 by using such words.']),
  ('Number detective',['Numbers have patterns. 100, 200 and 300 are all hundreds. 123, 345 and 789 have digits going up by one.','Numbers like 11, 22 and 33 have twin digits, and numbers like 111, 222 and 333 have triplet digits.','We can match quantities with ranges. The number of children in a school is probably between 201 and 500, and the stars in the sky are more than 1000.'])],
 [('Write 832 as hundreds, tens and ones.',[('The hundreds digit is 8.','The first digit.'),('The tens digit is 3 and the ones digit is 2.','Read each digit by place.'),('832 = 8 hundreds + 3 tens + 2 ones = 800 + 30 + 2.','Expanded form.')]),
  ('Which hundreds does 468 lie between?',[('Look at the hundreds digit, 4.','The number is more than 400.'),('The next hundred is 500.','Add 100.'),('468 lies between 400 and 500.','Closer to 500 than 400.')]),
  ('A crane at 667 wants to reach 700. How many steps does it need?',[('700 - 667 is the gap.','Subtract.'),('667 + 3 = 670, 670 + 30 = 700.','Count up in friendly steps.'),('So 33 steps.','Check: 667 + 33 = 700.')])],
 ('Explain how to write 504 using hundreds, tens and ones.',['5 hundreds','0 tens','4 ones','Zero holds the tens place'],['504 has 54 tens','Zero can be left out']),
 ['A number up to 1000 is made of hundreds, tens and ones.','Ten hundreds make a thousand.','A number lies between two hundreds, fifties and tens.','The same number can be written in many ways.','Patterns in numbers help us count and guess.'],
 [N('1',1,'How many hundreds are in 832?',8,'8 hundreds, 3 tens, 2 ones.',[(3,'3 is the tens digit'),(2,'2 is the ones digit')]),
  N('2',1,'How many tens are in 504 when we read it digit by digit?',0,'504 has 5 hundreds, 0 tens, 4 ones.',[(5,'5 is hundreds'),(4,'4 is ones')]),
  N('3',1,'What comes after 999?',1000,'999 + 1 = 1000.',[(900,'That comes before'),(990,'That comes before')]),
  M('4',1,'Which two hundreds does 468 lie between?','400 and 500',[('300 and 400','468 is more than 400'),('500 and 600','468 is less than 500')],'468 is between 400 and 500.'),
  N('5',2,'300 + 60 + 8 = ?',368,'3 hundreds, 6 tens and 8 ones.',[(3068,'Write the digits by place'),(38,'Do not drop the hundreds')]),
  N('6',2,'400 - 32 = ?',368,'400 - 30 = 370 and 370 - 2 = 368.',[(372,'That is adding'),(378,'Subtract 32')]),
  N('7',2,'How many steps from 667 to 700?',33,'667 + 33 = 700.',[(43,'Check 667 + 43'),(37,'667 + 37 = 704')]),
  F('8',2,'Ten hundreds make one thousand.',True,'10 × 100 = 1000.'),
  M('9',2,'Which number is between 595 and 605?','600',[('590','590 is less than 595'),('610','610 is more than 605')],'600 is between them.'),
  N('10',2,'Two more than 610 is?',612,'610 + 2 = 612.',[(608,'That is two less'),(620,'That is 10 more')]),
  N('11',3,'Five less than 625 is?',620,'625 - 5 = 620.',[(630,'That is 5 more'),(615,'That is 10 less')]),
  M('12',3,'The number of stars in the sky is probably?','More than 1000',[('0 to 10','That is far too few'),('11 to 50','That is too few')],'There are far more than a thousand stars.')],
 svgs=[('c3-hundreds2','A number line with jumps of 17 and 33 from 650 to 700','Jump to the nearest hundred first.')],
 keep=['hundreds','tens','ones','thousand'])
